      "keystrokes": "wget -q -O /app/lib/h2.jar https://repo1.maven.org/maven2/com/h2database/h2/1.3.176/h2-1.3.176.jar && echo \"h2 jar downloaded: $(ls -l /app/lib/h2.jar | awk '{print $5}') bytes\"\n",
      "duration": 5.0
    },
    {
      "keystrokes": "cat > /app/src/BankBatchJob.java <<'EOF'\nimport java.io.*;\nimport java.math.*;\nimport java.security.*;\nimport java.sql.*;\nimport java.text.*;\nimport java.util.*;\n\npublic class BankBatchJob {\n\n    // Must be a single literal string and used at runtime.\n    private static final String JDBC_URL = \"jdbc:h2:/app/output/bankdb;MODE=DB2\";\n\n    private static final File DATA_DIR = new File(\"/app/data\");\n    private static final File OUT_DIR = new File(\"/app/output\");\n\n    private static final RoundingMode RM = RoundingMode.HALF_EVEN;\n\n    private static final TimeZone UTC = TimeZone.getTimeZone(\"UTC\");\n\n    private static final SimpleDateFormat YYYY_MM_DD = new SimpleDateFormat(\"yyyy-MM-dd\");\n    static {\n        YYYY_MM_DD.setLenient(false);\n        YYYY_MM_DD.setTimeZone(UTC);\n    }\n\n    private static class Account {\n        String accountId;\n        Date openedAt;\n        BigDecimal startBalance;\n        BigDecimal baseApr;\n        BigDecimal promoApr;\n        int promoDays;\n        BigDecimal tierThreshold;\n        BigDecimal tierApr;\n        String currency;\n        String feePlan;\n\n        // computed\n        BigDecimal eodBalance;\n        BigDecimal apr;\n        BigDecimal dailyInterestRaw;\n    }\n\n    private static class FeeRule {\n        String feePlan;\n        String appliesTo; // DEBIT/CREDIT/ALL\n        BigDecimal flatFee;\n        BigDecimal pctFee;\n        BigDecimal minFee;\n        BigDecimal maxFee;\n    }\n\n    private static class Txn {\n        int rowNum; // 1-based data row\n        String txId;\n        String accountId;\n        Date effectiveDate;\n        BigDecimal amount;\n        String currency;\n        String status;\n        String reversalOf;\n\n        boolean valid;\n        String reason; // if skipped\n\n        // derived for processing\n        BigDecimal amountAcct; // converted to account currency, 2dp\n        BigDecimal fee; // 2dp\n        BigDecimal adjusted; // 2dp\n    }\n\n    private static class FxRate {\n        Date rateDate;\n        String from;\n        String to;\n        BigDecimal rate; // as provided\n    }\n\n    public static void main(String[] args) throws Exception {\n        OUT_DIR.mkdirs();\n\n        // Clean known outputs for deterministic reruns.\n        deleteIfExists(new File(OUT_DIR, \"interest.csv\"));\n        deleteIfExists(new File(OUT_DIR, \"exceptions.csv\"));\n        deleteIfExists(new File(OUT_DIR, \"stats.json\"));\n        deleteIfExists(new File(OUT_DIR, \"bankdb.h2.db\"));\n        deleteIfExists(new File(OUT_DIR, \"bankdb.trace.db\"));\n        deleteIfExists(new File(OUT_DIR, \"bankdb.lock.db\"));\n\n        Date bizDate = readBizDate(new File(DATA_DIR, \"biz_date.txt\"));\n\n        Map<String, Account> accounts = readAccounts(new File(DATA_DIR, \"accounts.csv\"));\n        Map<String, FeeRule> feeRules = readFeeRules(new File(DATA_DIR, \"fee_rules.csv\"));\n        List<String> pivots = readPivots(new File(DATA_DIR, \"fx_pivots.csv\"));\n        List<FxRate> fxRates = readFxRates(new File(DATA_DIR, \"fx_rates.csv\"));\n        List<Txn> txns = readTxns(new File(DATA_DIR, \"transactions.csv\"));\n\n        // Precompute tx_id set.\n        Set<String> txIdSet = new HashSet<String>();\n        for (Txn t : txns) txIdSet.add(t.txId);\n\n        // Determine REVERSED tx_ids: both rows if any row has reversal_of pointing to a tx_id in the file.\n        Set<String> reversedTxIds = new HashSet<String>();\n        for (Txn t : txns) {\n            if (t.reversalOf != null && t.reversalOf.length() > 0) {\n                if (txIdSet.contains(t.reversalOf)) {\n                    reversedTxIds.add(t.txId);\n                    reversedTxIds.add(t.reversalOf);\n                }\n            }\n        }\n\n        // Track duplicates: any tx_id after first appearance (even if first row invalid)\n        Set<String> seen = new HashSet<String>();\n\n        int validTxs = 0;\n        int skippedTxs = 0;\n\n        // Process each txn in file order applying reason precedence.\n        for (Txn t : txns) {\n            String reason = null;\n\n            boolean isDuplicate = seen.contains(t.txId);\n            seen.add(t.txId);\n\n            if (reversedTxIds.contains(t.txId)) {\n                reason = \"REVERSED\";\n            } else if (t.reversalOf != null && t.reversalOf.length() > 0 && !txIdSet.contains(t.reversalOf)) {\n                reason = \"REVERSAL_MISSING\";\n            } else if (!accounts.containsKey(t.accountId)) {\n                reason = \"ACCOUNT_MISSING\";\n            } else {\n                Account acct = accounts.get(t.accountId);\n                // FX_MISSING check is before date/status/duplicate.\n                BigDecimal fx = null;\n                if (t.currency.equals(acct.currency)) {\n                    fx = BigDecimal.ONE.setScale(10, RM);\n                } else {\n                    fx = resolveFxRate(fxRates, pivots, t.currency, acct.currency, t.effectiveDate);\n                    if (fx == null) {\n                        reason = \"FX_MISSING\";\n                    }\n                }\n\n                if (reason == null) {\n                    if (t.effectiveDate.after(bizDate)) {\n                        reason = \"AFTER_BIZ_DATE\";\n                    } else if (!\"POSTED\".equals(t.status)) {\n                        reason = t.status;\n                    } else if (isDuplicate) {\n                        reason = \"DUPLICATE\";\n                    } else {\n                        // Valid. Apply conversion + fees.\n                        t.amountAcct = t.amount.multiply(fx).setScale(2, RM);\n                        FeeRule fr = feeRules.get(acct.feePlan);\n                        t.fee = computeFee(fr, t.amountAcct);\n                        t.adjusted = t.amountAcct.subtract(t.fee).setScale(2, RM);\n                        t.valid = true;\n                        validTxs++;\n                    }\n                }\n            }\n\n            if (reason != null) {\n                t.valid = false;\n                t.reason = reason;\n                skippedTxs++;\n            }\n        }\n\n        // Aggregate balances.\n        for (Account a : accounts.values()) {\n            BigDecimal sum = BigDecimal.ZERO.setScale(2, RM);\n            for (Txn t : txns) {\n                if (t.valid && a.accountId.equals(t.accountId)) {\n                    sum = sum.add(t.adjusted).setScale(2, RM);\n                }\n            }\n            a.eodBalance = a.startBalance.add(sum).setScale(2, RM);\n\n            boolean promoActive = false;\n            if (a.promoDays > 0) {\n                int days = daysBetween(a.openedAt, bizDate);\n                promoActive = days < a.promoDays;\n            }\n\n            BigDecimal apr = a.baseApr;\n            if (a.eodBalance.compareTo(a.tierThreshold) >= 0) {\n                apr = apr.add(a.tierApr);\n            }\n            if (promoActive) {\n                apr = apr.add(a.promoApr);\n            }\n            a.apr = apr;\n\n            BigDecimal principal = a.eodBalance.max(BigDecimal.ZERO);\n            // daily_interest_raw = principal * apr/365 (HALF_EVEN 10dp)\n            BigDecimal dailyRate = a.apr.divide(new BigDecimal(\"365\"), 10, RM);\n            a.dailyInterestRaw = principal.multiply(dailyRate).setScale(10, RM);\n        }\n\n        // Write interest.csv\n        File interestFile = new File(OUT_DIR, \"interest.csv\");\n        writeInterestCsv(interestFile, bizDate, accounts);\n\n        // Compute md5 of interest.csv bytes\n        String reportMd5 = md5HexOfFile(interestFile);\n\n        // Write exceptions.csv\n        File exceptionsFile = new File(OUT_DIR, \"exceptions.csv\");\n        writeExceptionsCsv(exceptionsFile, txns);\n\n        // total_interest = sum(daily_interest_raw keep 10dp) rounded to 2dp\n        BigDecimal totalInterestRaw = BigDecimal.ZERO.setScale(10, RM);\n        for (Account a : accounts.values()) {\n            totalInterestRaw = totalInterestRaw.add(a.dailyInterestRaw).setScale(10, RM);\n        }\n        BigDecimal totalInterest = totalInterestRaw.setScale(2, RM);\n\n        // stats.json single line, no newline\n        File statsFile = new File(OUT_DIR, \"stats.json\");\n        writeStatsJsonNoNewline(statsFile, bizDate, accounts.size(), validTxs, skippedTxs, totalInterest, reportMd5);\n\n        // Create H2 DB\n        writeH2Db(bizDate, accounts, txns, validTxs, skippedTxs, reportMd5);\n    }\n\n    private static void deleteIfExists(File f) {\n        if (f.exists()) {\n            // best effort\n            f.delete();\n        }\n    }\n\n    private static Date readBizDate(File f) throws Exception {\n        String s = readAllTrimmed(f);\n        return parseDate(s);\n    }\n\n    private static String readAllTrimmed(File f) throws Exception {\n        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), \"UTF-8\"));\n        try {\n            StringBuilder sb = new StringBuilder();\n            String line;\n            while ((line = br.readLine()) != null) sb.append(line);\n            return sb.toString().trim();\n        } finally {\n            br.close();\n        }\n    }\n\n    private static Map<String, Account> readAccounts(File f) throws Exception {\n        List<String[]> rows = readCsv(f);\n        Map<String, Account> m = new HashMap<String, Account>();\n        // header expected\n        for (int i = 1; i < rows.size(); i++) {\n            String[] r = rows.get(i);\n            Account a = new Account();\n            a.accountId = r[0];\n            a.openedAt = parseDate(r[1]);\n            a.startBalance = new BigDecimal(r[2]).setScale(2, RM);\n            a.baseApr = new BigDecimal(r[3]);\n            a.promoApr = new BigDecimal(r[4]);\n            a.promoDays = Integer.parseInt(r[5]);\n            a.tierThreshold = new BigDecimal(r[6]).setScale(2, RM);\n            a.tierApr = new BigDecimal(r[7]);\n            a.currency = r[8];\n            a.feePlan = r[9];\n            m.put(a.accountId, a);\n        }\n        return m;\n    }\n\n    private static Map<String, FeeRule> readFeeRules(File f) throws Exception {\n        List<String[]> rows = readCsv(f);\n        Map<String, FeeRule> m = new HashMap<String, FeeRule>();\n        for (int i = 1; i < rows.size(); i++) {\n            String[] r = rows.get(i);\n            FeeRule fr = new FeeRule();\n            fr.feePlan = r[0];\n            fr.appliesTo = r[1];\n            fr.flatFee = new BigDecimal(r[2]);\n            fr.pctFee = new BigDecimal(r[3]);\n            fr.minFee = new BigDecimal(r[4]);\n            fr.maxFee = new BigDecimal(r[5]);\n            m.put(fr.feePlan, fr);\n        }\n        return m;\n    }\n\n    private static List<String> readPivots(File f) throws Exception {\n        List<String[]> rows = readCsv(f);\n        List<String> pivots = new ArrayList<String>();\n        for (int i = 1; i < rows.size(); i++) {\n            pivots.add(rows.get(i)[0]);\n        }\n        return pivots;\n    }\n\n    private static List<FxRate> readFxRates(File f) throws Exception {\n        List<String[]> rows = readCsv(f);\n        List<FxRate> list = new ArrayList<FxRate>();\n        for (int i = 1; i < rows.size(); i++) {\n            String[] r = rows.get(i);\n            FxRate fr = new FxRate();\n            fr.rateDate = parseDate(r[0]);\n            fr.from = r[1];\n            fr.to = r[2];\n            fr.rate = new BigDecimal(r[3]);\n            list.add(fr);\n        }\n        return list;\n    }\n\n    private static List<Txn> readTxns(File f) throws Exception {\n        List<String[]> rows = readCsv(f);\n        List<Txn> list = new ArrayList<Txn>();\n        for (int i = 1; i < rows.size(); i++) {\n            String[] r = rows.get(i);\n            Txn t = new Txn();\n            t.rowNum = i; // 1-based data row\n            t.txId = r[0];\n            t.accountId = r[1];\n            t.effectiveDate = parseDate(r[2]);\n            t.amount = new BigDecimal(r[3]).setScale(2, RM);\n            t.currency = r[4];\n            t.status = r[5];\n            t.reversalOf = r.length > 6 ? r[6] : \"\";\n            if (t.reversalOf == null) t.reversalOf = \"\";\n            list.add(t);\n        }\n        return list;\n    }\n\n    private static List<String[]> readCsv(File f) throws Exception {\n        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), \"UTF-8\"));\n        try {\n            List<String[]> rows = new ArrayList<String[]>();\n            String line;\n            while ((line = br.readLine()) != null) {\n                // simple CSV (no quoted fields expected)\n                String[] parts = line.split(\",\", -1);\n                for (int i = 0; i < parts.length; i++) parts[i] = parts[i].trim();\n                rows.add(parts);\n            }\n            return rows;\n        } finally {\n            br.close();\n        }\n    }\n\n    private static Date parseDate(String s) throws ParseException {\n        synchronized (YYYY_MM_DD) {\n            return YYYY_MM_DD.parse(s);\n        }\n    }\n\n    private static String formatDate(Date d) {\n        synchronized (YYYY_MM_DD) {\n            return YYYY_MM_DD.format(d);\n        }\n    }\n\n    private static int daysBetween(Date start, Date end) {\n        long ms = end.getTime() - start.getTime();\n        return (int)(ms / 86400000L);\n    }\n\n    private static BigDecimal computeFee(FeeRule fr, BigDecimal amountAcct) {\n        if (fr == null) {\n            return BigDecimal.ZERO.setScale(2, RM);\n        }\n        int sign = amountAcct.signum();\n        boolean debit = sign < 0;\n        boolean credit = sign > 0;\n\n        boolean applies = false;\n        if (\"ALL\".equals(fr.appliesTo)) applies = true;\n        else if (\"DEBIT\".equals(fr.appliesTo) && debit) applies = true;\n        else if (\"CREDIT\".equals(fr.appliesTo) && credit) applies = true;\n\n        if (!applies) {\n            return BigDecimal.ZERO.setScale(2, RM);\n        }\n\n        BigDecimal base = fr.flatFee.add(fr.pctFee.multiply(amountAcct.abs()));\n        BigDecimal fee = base.setScale(2, RM);\n        if (fee.compareTo(fr.minFee) < 0) fee = fr.minFee;\n        if (fee.compareTo(fr.maxFee) > 0) fee = fr.maxFee;\n        fee = fee.setScale(2, RM);\n        return fee;\n    }\n\n    private static BigDecimal resolveFxRate(List<FxRate> allRates, List<String> pivots, String from, String to, Date effectiveDate) {\n        BigDecimal direct = resolveFxLeg(allRates, from, to, effectiveDate);\n        if (direct != null) return direct;\n\n        // Try pivots in order.\n        for (int i = 0; i < pivots.size(); i++) {\n            String p = pivots.get(i);\n            if (p.equals(from) || p.equals(to)) continue;\n            BigDecimal leg1 = resolveFxLeg(allRates, from, p, effectiveDate);\n            if (leg1 == null) continue;\n            BigDecimal leg2 = resolveFxLeg(allRates, p, to, effectiveDate);\n            if (leg2 == null) continue;\n            return leg1.multiply(leg2).setScale(10, RM);\n        }\n        return null;\n    }\n\n    private static BigDecimal resolveFxLeg(List<FxRate> allRates, String from, String to, Date effectiveDate) {\n        FxRate bestDirect = latestRate(allRates, from, to, effectiveDate);\n        FxRate bestReverse = latestRate(allRates, to, from, effectiveDate);\n\n        if (bestDirect == null && bestReverse == null) return null;\n        if (bestDirect != null && bestReverse == null) {\n            return bestDirect.rate.setScale(10, RM);\n        }\n        if (bestDirect == null && bestReverse != null) {\n            return BigDecimal.ONE.divide(bestReverse.rate, 10, RM);\n        }\n\n        // Both exist: choose newer one; if tied, use direct.\n        int cmp = bestDirect.rateDate.compareTo(bestReverse.rateDate);\n        if (cmp > 0) {\n            return bestDirect.rate.setScale(10, RM);\n        } else if (cmp < 0) {\n            return BigDecimal.ONE.divide(bestReverse.rate, 10, RM);\n        } else {\n            return bestDirect.rate.setScale(10, RM);\n        }\n    }\n\n    private static FxRate latestRate(List<FxRate> allRates, String from, String to, Date effectiveDate) {\n        FxRate best = null;\n        for (int i = 0; i < allRates.size(); i++) {\n            FxRate r = allRates.get(i);\n            if (!r.from.equals(from)) continue;\n            if (!r.to.equals(to)) continue;\n            if (r.rateDate.after(effectiveDate)) continue;\n            if (best == null || r.rateDate.after(best.rateDate)) {\n                best = r;\n            }\n        }\n        return best;\n    }\n\n    private static void writeInterestCsv(File f, Date bizDate, Map<String, Account> accounts) throws Exception {\n        List<String> ids = new ArrayList<String>(accounts.keySet());\n        Collections.sort(ids);\n        OutputStream os = new FileOutputStream(f);\n        Writer w = new OutputStreamWriter(os, \"UTF-8\");\n        try {\n            w.write(\"account_id,biz_date,eod_balance,apr,daily_interest\\n\");\n            for (int i = 0; i < ids.size(); i++) {\n                Account a = accounts.get(ids.get(i));\n                BigDecimal apr6 = a.apr.setScale(6, RM);\n                BigDecimal di2 = a.dailyInterestRaw.setScale(2, RM);\n                w.write(a.accountId);\n                w.write(',');\n                w.write(formatDate(bizDate));\n                w.write(',');\n                w.write(a.eodBalance.setScale(2, RM).toPlainString());\n                w.write(',');\n                w.write(apr6.toPlainString());\n                w.write(',');\n                w.write(di2.toPlainString());\n                w.write(\"\\n\");\n            }\n        } finally {\n            w.close();\n        }\n    }\n\n    private static void writeExceptionsCsv(File f, List<Txn> txns) throws Exception {\n        OutputStream os = new FileOutputStream(f);\n        Writer w = new OutputStreamWriter(os, \"UTF-8\");\n        try {\n            w.write(\"row_num,tx_id,reason\\n\");\n            for (int i = 0; i < txns.size(); i++) {\n                Txn t = txns.get(i);\n                if (t.valid) continue;\n                w.write(Integer.toString(t.rowNum));\n                w.write(',');\n                w.write(t.txId);\n                w.write(',');\n                w.write(t.reason);\n                w.write(\"\\n\");\n            }\n        } finally {\n            w.close();\n        }\n    }\n\n    private static String md5HexOfFile(File f) throws Exception {\n        MessageDigest md = MessageDigest.getInstance(\"MD5\");\n        InputStream is = new FileInputStream(f);\n        try {\n            byte[] buf = new byte[8192];\n            int n;\n            while ((n = is.read(buf)) > 0) {\n                md.update(buf, 0, n);\n            }\n        } finally {\n            is.close();\n        }\n        byte[] dig = md.digest();\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < dig.length; i++) {\n            int b = dig[i] & 0xFF;\n            String hx = Integer.toHexString(b);\n            if (hx.length() == 1) sb.append('0');\n            sb.append(hx);\n        }\n        return sb.toString();\n    }\n\n    private static void writeStatsJsonNoNewline(File f, Date bizDate, int accounts, int validTxs, int skippedTxs,\n                                               BigDecimal totalInterest, String reportMd5) throws Exception {\n        StringBuilder sb = new StringBuilder();\n        sb.append('{');\n        sb.append(\"\\\"business_date\\\":\\\"\").append(formatDate(bizDate)).append(\"\\\"\");\n        sb.append(\",\\\"accounts\\\":\").append(accounts);\n        sb.append(\",\\\"valid_txs\\\":\").append(validTxs);\n        sb.append(\",\\\"skipped_txs\\\":\").appe